template <std::size_t Size>
[[nodiscard]] bool contains(
    const CodePointRange (&ranges)[Size],
    const char32_t value
) noexcept {
    std::size_t first = 0U;
    std::size_t last = Size;
    while (first < last) {
        const std::size_t middle = first + (last - first) / 2U;
        if (value < ranges[middle].first) {
            last = middle;
        } else if (value > ranges[middle].last) {
            first = middle + 1U;
        } else {
            return true;
        }
    }
    return false;
}

[[nodiscard]] bool letter_or_digit(const char32_t value) noexcept {
    return contains(kLetterOrDigitRanges, value);
}

[[nodiscard]] bool cased(const char32_t value) noexcept {
    return contains(kCasedRanges, value);
}

[[nodiscard]] bool case_ignorable(const char32_t value) noexcept {
    return contains(kCaseIgnorableRanges, value);
}

[[nodiscard]] bool whitespace(const char32_t value) noexcept {
    // Kotlin/JVM Char.isWhitespace is Character.isWhitespace || Character.isSpaceChar.
    return (value >= 0x0009U && value <= 0x000DU) ||
           (value >= 0x001CU && value <= 0x0020U) ||
           value == 0x00A0U || value == 0x1680U ||
           (value >= 0x2000U && value <= 0x200AU) ||
           (value >= 0x2028U && value <= 0x2029U) ||
           value == 0x202FU || value == 0x205FU || value == 0x3000U;
}

struct SourceScalar final {
    char32_t value = 0U;
    std::size_t utf16_start = 0U;
    std::size_t utf16_end = 0U;
};

[[nodiscard]] std::vector<SourceScalar> decode_utf8(const std::string_view text) {
    std::vector<SourceScalar> result;
    result.reserve(text.size());
    std::size_t byte = 0U;
    std::size_t utf16 = 0U;
    while (byte < text.size()) {
        const auto lead = static_cast<unsigned char>(text[byte]);
        char32_t value = 0xFFFDU;
        std::size_t width = 1U;
        if (lead < 0x80U) {
            value = lead;
        } else {
            const std::size_t expected = lead >= 0xC2U && lead <= 0xDFU ? 2U
                : lead >= 0xE0U && lead <= 0xEFU ? 3U
                : lead >= 0xF0U && lead <= 0xF4U ? 4U : 0U;
            if (expected != 0U && byte + expected <= text.size()) {
                char32_t decoded = static_cast<char32_t>(
                    lead & (expected == 2U ? 0x1FU : expected == 3U ? 0x0FU : 0x07U)
                );
                bool valid = true;
                for (std::size_t offset = 1U; offset < expected; ++offset) {
                    const auto continuation = static_cast<unsigned char>(text[byte + offset]);
                    if ((continuation & 0xC0U) != 0x80U) {
                        valid = false;
                        break;
                    }
                    decoded = (decoded << 6U) | static_cast<char32_t>(continuation & 0x3FU);
                }
                const char32_t minimum = expected == 2U ? 0x80U
                    : expected == 3U ? 0x800U : 0x10000U;
                if (valid && decoded >= minimum && decoded <= 0x10FFFFU &&
                    !(decoded >= 0xD800U && decoded <= 0xDFFFU)) {
                    value = decoded;
                    width = expected;
                }
            }
        }
        const std::size_t scalar_width = value > 0xFFFFU ? 2U : 1U;
        result.push_back(SourceScalar{value, utf16, utf16 + scalar_width});
        utf16 += scalar_width;
        byte += width;
    }
    return result;
}

[[nodiscard]] bool final_sigma(
    const std::span<const SourceScalar> source,
    const std::size_t index
) noexcept {
    bool preceded_by_cased = false;
    for (std::size_t cursor = index; cursor > 0U; --cursor) {
        const char32_t value = source[cursor - 1U].value;
        if (case_ignorable(value)) continue;
        preceded_by_cased = cased(value);
        break;
    }
    if (!preceded_by_cased) return false;
    for (std::size_t cursor = index + 1U; cursor < source.size(); ++cursor) {
        const char32_t value = source[cursor].value;
        if (case_ignorable(value)) continue;
        return !cased(value);
    }
    return true;
}

[[nodiscard]] char32_t simple_lower(const char32_t value) noexcept {
    std::size_t first = 0U;
    std::size_t last = std::size(kLowerRanges);
    while (first < last) {
        const std::size_t middle = first + (last - first) / 2U;
        const LowerRange& range = kLowerRanges[middle];
        if (value < range.first) {
            last = middle;
        } else if (value > range.last) {
            first = middle + 1U;
        } else if ((value - range.first) % range.stride == 0U) {
            return static_cast<char32_t>(
                static_cast<std::int64_t>(value) + range.delta
            );
        } else {
            break;
        }
    }
    first = 0U;
    last = std::size(kLowerSingles);
    while (first < last) {
        const std::size_t middle = first + (last - first) / 2U;
        if (value < kLowerSingles[middle].source) {
            last = middle;
        } else if (value > kLowerSingles[middle].source) {
            first = middle + 1U;
        } else {
            return kLowerSingles[middle].target;
        }
    }
    return value;
}

